Solution A: function createSortingVisualizer(canvasId){const canvas=document.getElementById(canvasId);const ctx=canvas.getContext('2d');canvas.width=500;canvas.height=500;const W=canvas.width;const H=canvas.height;const ARR_SIZE=100;let data=new Array(ARR_SIZE);let barWidth=W/ARR_SIZE;let comparisons=0,swaps=0;let algorithm='Bubble';let speed=100;let mode='continuous';let running=false;let gen=null;let callDepth=0;let highlight={};let workRange=null;const container=document.createElement('div');container.style.display='flex';container.style.flexDirection='column';container.style.alignItems='center';canvas.parentNode.insertBefore(container,canvas);container.appendChild(canvas);const ctrlBar=document.createElement('div');ctrlBar.style.margin='10px';container.appendChild(ctrlBar);const algoSelect=document.createElement('select');['Bubble','Quick','Merge','Heap','Radix'].forEach(a=>{const o=document.createElement('option');o.value=a;o.textContent=a;algoSelect.appendChild(o);});ctrlBar.appendChild(algoSelect);const speedLabel=document.createElement('label');speedLabel.textContent=' Speed:';ctrlBar.appendChild(speedLabel);const speedSlider=document.createElement('input');speedSlider.type='range';speedSlider.min='10';speedSlider.max='500';speedSlider.value='100';speedSlider.style.margin='0 5px';ctrlBar.appendChild(speedSlider);const modeLabel=document.createElement('label');modeLabel.textContent=' Step mode:';ctrlBar.appendChild(modeLabel);const modeCheck=document.createElement('input');modeCheck.type='checkbox';ctrlBar.appendChild(modeCheck);const stepBtn=document.createElement('button');stepBtn.textContent='Next Step';stepBtn.disabled=true;ctrlBar.appendChild(stepBtn);const scrambleSelect=document.createElement('select');['Random','Reverse','Nearly Sorted'].forEach(p=>{const o=document.createElement('option');o.value=p;o.textContent=p;scrambleSelect.appendChild(o);});ctrlBar.appendChild(scrambleSelect);const scrambleBtn=document.createElement('button');scrambleBtn.textContent='Scramble';ctrlBar.appendChild(scrambleBtn);const infoBar=document.createElement('div');infoBar.style.margin='10px';container.appendChild(infoBar);const compSpan=document.createElement('span');compSpan.textContent='Comparisons: 0 ';infoBar.appendChild(compSpan);const swapSpan=document.createElement('span');swapSpan.textContent='Swaps: 0 ';infoBar.appendChild(swapSpan);const depthSpan=document.createElement('span');depthSpan.textContent='Call Depth: 0 ';infoBar.appendChild(depthSpan);const complexSpan=document.createElement('span');complexSpan.textContent=' Complexity: O(n²) ';infoBar.appendChild(complexSpan);function initArray(pattern){for(let i=0;i<ARR_SIZE;i++)data[i]=i+1;switch(pattern){case'Random':for(let i=ARR_SIZE-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[data[i],data[j]]=[data[j],data[i]];}break;case'Reverse':data.reverse();break;case'Nearly Sorted':for(let i=0;i<ARR_SIZE-2;i+=5){const j=i+Math.floor(Math.random()*5);[data[i],data[j]]=[data[j],data[i]];}break;}comparisons=swaps=0;updateCounters();draw();}function updateCounters(){compSpan.textContent='Comparisons: '+comparisons+' ';swapSpan.textContent='Swaps: '+swaps+' ';depthSpan.textContent='Call Depth: '+callDepth+' ';}function draw(){ctx.clearRect(0,0,W,H);if(workRange){ctx.fillStyle='rgba(0,255,0,0.1)';ctx.fillRect(workRange.low*barWidth,0,(workRange.high-workRange.low+1)*barWidth,H);}for(let i=0;i<ARR_SIZE;i++){let c='lightgray';if(highlight[i])c=highlight[i];ctx.fillStyle=c;ctx.fillRect(i*barWidth,H-data[i]/ARR_SIZE*H,barWidth-1,-data[i]/ARR_SIZE*H);}requestAnimationFrame(draw);}function setComplexity(){switch(algorithm){case'Bubble':complexSpan.textContent=' Complexity: O(n²) ';break;case'Quick':case'Merge':case'Heap':complexSpan.textContent=' Complexity: O(n log n) ';break;case'Radix':complexSpan.textContent=' Complexity: O(k·n) ';break;}}function* bubbleSort(){for(let i=0;i<ARR_SIZE;i++){for(let j=0;j<ARR_SIZE-i-1;j++){highlight[j]='red';highlight[j+1]='red';comparisons++;yield;highlight[j]=null;highlight[j+1]=null;if(data[j]>data[j+1]){[data[j],data[j+1]]=[data[j+1],data[j]];swaps++;highlight[j]='yellow';highlight[j+1]='yellow';yield;highlight[j]=null;highlight[j+1]=null;}}highlight[ARR_SIZE-i-1]='green';}for(let i=0;i<ARR_SIZE;i++)highlight[i]='green';}function* quickSort(lo,hi){if(lo<hi){callDepth++;workRange={low:lo,high:hi};let p=yield* partition(lo,hi);yield* quickSort(lo,p-1);yield* quickSort(p+1,hi);callDepth--;workRange=null;}}function* partition(lo,hi){let pivot=data[hi];highlight[hi]='blue';let i=lo-1;for(let j=lo;j<hi;j++){highlight[j]='red';comparisons++;yield;if(data[j]<pivot){i++;[data[i],data[j]]=[data[j],data[i]];swaps++;highlight[i]='yellow';highlight[j]='yellow';yield;highlight[i]=null;highlight[j]=null;}highlight[j]=null;}[data[i+1],data[hi]]=[data[hi],data[i+1]];swaps++;highlight[i+1]='yellow';highlight[hi]='yellow';yield;highlight[i+1]=null;highlight[hi]=null;highlight[hi]=null;return i+1;}function* mergeSort(l,r){if(l<r){callDepth++;let m=Math.floor((l+r)/2);workRange={low:l,high:r};yield* mergeSort(l,m);yield* mergeSort(m+1,r);yield* merge(l,m,r);callDepth--;workRange=null;}}function* merge(l,m,r){let left=data.slice(l,m+1);let right=data.slice(m+1,r+1);let i=0,j=0,k=l;while(i<left.length&&j<right.length){highlight[k]='red';comparisons++;yield;if(left[i]<=right[j]){data[k]=left[i];i++;}else{data[k]=right[j];j++;}swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}while(i<left.length){highlight[k]='red';yield;data[k]=left[i];i++;swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}while(j<right.length){highlight[k]='red';yield;data[k]=right[j];j++;swaps++;highlight[k]='yellow';yield;highlight[k]=null;k++;}}function* heapSort(){let n=ARR_SIZE;for(let i=Math.floor(n/2)-1;i>=0;i--)yield* heapify(n,i);for(let i=n-1;i>0;i--){[data[0],data[i]]=[data[i],data[0]];swaps++;highlight[0]='yellow';highlight[i]='yellow';yield;highlight[0]=null;highlight[i]=null;yield* heapify(i,0);}for(let i=0;i<ARR_SIZE;i++)highlight[i]='green';}function* heapify(n,i){let largest=i;let l=2*i+1;let r=2*i+2;if(l<n){highlight[l]='red';comparisons++;yield;if(data[l]>data[largest])largest=l;highlight[l]=null;}if(r<n){highlight[r]='red';comparisons++;yield;if(data[r]>data[largest])largest=r;highlight[r]=null;}if(largest!=i){[data[i],data[largest]]=[data[largest],data[i]];swaps++;highlight[i]='yellow';highlight[largest]='yellow';yield;highlight[i]=null;highlight[largest]=null;yield* heapify(n,largest);} }function* radixSort(){let max=Math.max(...data);let exp=1;while(Math.floor(max/exp)>0){yield* countingSort(exp);exp*=10;}for(let i=0;i<ARR_SIZE;i++)highlight[i]='green';}function* countingSort(exp){let output=new Array(ARR_SIZE);let count=new Array(10).fill(0);for(let i=0;i<ARR_SIZE;i++){let idx=Math.floor(data[i]/exp)%10;count[idx]++;comparisons++;yield;}for(let i=1;i<10;i++){count[i]+=count[i-1];}for(let i=ARR_SIZE-1;i>=0;i--){let idx=Math.floor(data[i]/exp)%10;output[count[idx]-1]=data[i];count[idx]--;swaps++;highlight[i]='yellow';yield;highlight[i]=null;}for(let i=0;i<ARR_SIZE;i++){data[i]=output[i];} }function start(){if(running)return;running=true;stepBtn.disabled=true;switch(algorithm){case'Bubble':gen=bubbleSort();break;case'Quick':gen=quickSort(0,ARR_SIZE-1);break;case'Merge':gen=mergeSort(0,ARR_SIZE-1);break;case'Heap':gen=heapSort();break;case'Radix':gen=radixSort();break;}if(mode==='continuous'){runContinuous();}else{stepBtn.disabled=false;}}function pause(){running=false;stepBtn.disabled=true;}function runContinuous(){if(!running){pause();return;}const {value,done}=gen.next();if(done){running=false;stepBtn.disabled=true;return;}updateCounters();setTimeout(runContinuous,speed);}function nextStep(){if(!running)return;const {value,done}=gen.next();if(done){running=false;stepBtn.disabled=true;return;}updateCounters();}algoSelect.addEventListener('change',e=>{algorithm=e.target.value;setComplexity();});speedSlider.addEventListener('input',e=>{speed=+e.target.value;});modeCheck.addEventListener('change',e=>{mode=e.target.checked?'step':'continuous';if(mode==='step'){pause();stepBtn.disabled=false;}else{stepBtn.disabled=true;}});stepBtn.addEventListener('click',nextStep);scrambleBtn.addEventListener('click',()=>{initArray(scrambleSelect.value);});canvas.addEventListener('click',()=>{if(!running)start();});initArray('Random');setComplexity();draw();}
}

